import type { Meta, StoryObj } from "@storybook/react-webpack5";

import { CloseIcon } from "@egov3/graphics/General/Close";
import { useState } from "react";

import { Label } from "../../baseComponents";

const meta = {
  title: "BaseComponents/Label",
  component: Label,
  parameters: {
    layout: "centered",
  },
  tags: ["autodocs"],
  args: {
    variant: "big",
    isSpaced: false,
    text: "Label",
    Icon: CloseIcon,
  },
  argTypes: {
    variant: { control: "select", options: ["big", "small", "tiny"] },
    isSpaced: { control: "boolean" },
    text: { control: "text" },
    Icon: { control: "object" },
  },
  render: (args) => (
    <div
      style={{
        backgroundColor: "bisque",
        width: "200px",
      }}
    >
      <Label {...args} />
    </div>
  ),
} satisfies Meta<typeof Label>;

export default meta;
type Story = StoryObj<typeof meta>;

export const BigVariant: Story = {
  args: {
    variant: "big",
  },
};

export const SmallVariant: Story = {
  args: {
    variant: "small",
  },
};

export const TinyVariant: Story = {
  args: {
    variant: "tiny",
  },
};

export const Spaced: Story = {
  args: {
    variant: "big",
    isSpaced: true,
  },
};

export const BigVariantWithIcon: Story = {
  args: {
    variant: "big",
    Icon: CloseIcon,
  },
};

export const SmallVariantWithIcon: Story = {
  args: {
    variant: "small",
    Icon: CloseIcon,
  },
};

export const Interactive: Story = {
  render: (args) => {
    const InteractiveComponent = () => {
      const [pressed, setPressed] = useState(false);
      return (
        <div
          style={{
            backgroundColor: "bisque",
            width: "250px",
          }}
        >
          <Label
            {...args}
            onAction={() => {
              setPressed((val) => !val);
            }}
            text={`Button has ${pressed ? "" : "not"} pressed`}
          />
        </div>
      );
    };
    return <InteractiveComponent />;
  },
  args: {
    variant: "big",
    isSpaced: true,
    text: "Label",
    Icon: CloseIcon,
  },
};
